<?php
$spDevices = json_decode($dvl_txt ?? '{}', true) ?: [];
$spDetails = json_decode($detail_rgl_txt ?? '{}', true) ?: [];
$spInverters = [];
foreach ($spDevices as $spId => $spDevice) {
    $spModel = $spDevice['model'] ?? '';
    if (($spDetails[$spModel]['type'] ?? '') === 'inverter') $spInverters[$spId] = $spDevice;
}
$spChannelConfig = json_decode(@file_get_contents('./config/solar_performance.json'), true);
if (!is_array($spChannelConfig)) $spChannelConfig = [];
require_once __DIR__.'/user_permission.php';
$spCanEditConfig=strtolower((string)($_SESSION['user_type']??''))==='superadmin'||mdb_can_function('device_config');
$spAutomationConfig=json_decode(@file_get_contents('./config/automation_control.json'),true)?:[];
$spMainMeter=(string)($spAutomationConfig['main_meter']??'');
?>
