<script>
(()=>{const create=Highcharts.chart;Highcharts.chart=function(renderTo,options,callback){const element=typeof renderTo==='string'?document.getElementById(renderTo):renderTo,container=element?.parentElement;if(container?.classList.contains('sp-hc-all')){container.classList.add('sp-chart-building');const loader=document.createElement('div');loader.className='sp-chart-loader';loader.innerHTML='<i class="fa-solid fa-chart-column"></i> กำลังโหลดกราฟ…';container.appendChild(loader)}const chart=create.call(this,renderTo,options,function(instance){requestAnimationFrame(()=>requestAnimationFrame(()=>{container?.querySelector('.sp-chart-loader')?.remove();container?.classList.remove('sp-chart-building');instance.reflow();callback?.call(this,instance)}))});return chart}})();
</script>
