<script>
(()=>{const mark=()=>document.querySelectorAll('#spGrid .sp-card').forEach(card=>{const area=card.querySelector('.sp-strings,.sp-highcharts-groups,.sp-hc-all');if(!area)return;const chart=(Highcharts.charts||[]).find(item=>item&&area.contains(item.renderTo)),hasChartData=!!chart?.series?.some(series=>series.points?.some(point=>Number.isFinite(point.y))),hasRawData=area.querySelectorAll('.sp-string').length>0,existing=area.querySelector('.sp-inverter-no-data');if(!hasChartData&&!hasRawData&&!existing){const empty=document.createElement('div');empty.className='sp-inverter-no-data';empty.innerHTML='<i class="fa-solid fa-circle-exclamation"></i><span>ไม่มีข้อมูล</span>';area.appendChild(empty)}else if((hasChartData||hasRawData)&&existing)existing.remove()});setInterval(mark,1000);setTimeout(mark,400)})();
</script>
