<script>
(()=>{
const devices=<?php echo json_encode($spInverters,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>,mapping=<?php echo json_encode($spChannelConfig,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>,mainMeter=<?=json_encode($spMainMeter)?>,grid=document.getElementById('spGrid'),search=document.getElementById('spSearch'),status=document.getElementById('spStatus'),updated=document.getElementById('spUpdated'),charts=new Map();let loading=false,todaySolarEnergy=null,deviceEnergyToday={},lastAll={};
