const layout=id=>{const points=[],bands=[];(Array.isArray(mapping[id])?mapping[id]:[]).forEach((row,channelIndex)=>{const start=points.length,channel=row.channel||'Channel '+(channelIndex+1),parameters=(Array.isArray(row.parameters)?row.parameters:[row.parameter]).filter(Boolean).sort((a,b)=>Number(String(a).match(/\d+/))-Number(String(b).match(/\d+/)));parameters.forEach(parameter=>points.push({parameter,channel,string:'String '+(String(parameter).match(/\d+$/)?.[0]||points.length+1)}));if(points.length>start)bands.push({from:start-.5,to:points.length-.5,color:channelIndex%2?'rgba(23,105,210,.035)':'rgba(230,163,33,.04)',label:{text:channel,rotation:0,y:12,style:{fontSize:'8px',color:'#8192a1'}}})});return{points,bands}};
