(()=>{const devices=<?php echo json_encode($spInverters,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>,channelConfig=<?php echo json_encode($spChannelConfig,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),num=v=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v)),grid=document.getElementById('spGrid'),search=document.getElementById('spSearch'),status=document.getElementById('spStatus');let latest={};const pick=(data,names)=>{for(const key of names)if(num(data[key]))return Number(data[key]);return null};
function draw(){let totalIn=0,totalOut=0,online=0,alerts=0,cards=[];Object.entries(devices).forEach(([id,device])=>{const d=latest[id]||{},pin=pick(d,['p_in']),pout=pick(d,['p_out','p_t']),energy=pick(d,['e_p']),currents=Object.keys(d).filter(k=>/^in_dca_\d+$/i.test(k)&&num(d[k])).sort((a,b)=>Number(a.match(/\d+/))-Number(b.match(/\d+/))),values=currents.map(k=>Number(d[k])),positive=values.filter(v=>v>0).sort((a,b)=>a-b),median=positive.length?(positive[Math.floor((positive.length-1)/2)]+positive[Math.ceil((positive.length-1)/2)])/2:0,eff=pin!==null&&pin>1&&pout!==null?pout/pin*100:null,age=d.dt?Date.now()/1000-Number(d.dt):999999,isOnline=age<=180&&!d.error;let state=!isOnline||values.some(v=>median>0&&v<median*.6)?'abnormal':values.some(v=>median>0&&v<median*.8)||eff!==null&&(eff<85||eff>101)?'watch':'normal';if(isOnline)online++;if(state!=='normal')alerts++;if(pin!==null)totalIn+=pin;if(pout!==null)totalOut+=pout;const q=(id+' '+(device.name||'')+' '+(device.model||'')).toLowerCase();if((search.value&&!q.includes(search.value.toLowerCase()))||(status.value!=='all'&&status.value!==state))return;const stateText={normal:'ปกติ',watch:'ควรติดตาม',abnormal:isOnline?'ผิดปกติ':'Offline'}[state];cards.push('<article class="sp-card '+state+'"><div class="sp-card-head"><div><b>'+esc(device.name||id)+'</b><small>'+esc(id)+' · '+esc(device.model||'')+'</small></div><div class="sp-card-actions"><span class="sp-state">'+stateText+'</span><a class="sp-card-edit" href="index.php?page=solar-performance-config&device='+encodeURIComponent(id)+'" title="แก้ไข Channel ของ '+esc(device.name||id)+'" aria-label="แก้ไข Channel"><i class="fa-solid fa-pen"></i></a></div></div><div class="sp-metrics"><div class="sp-metric"><small>DC Input</small><strong>'+(pin===null?'—':pin.toLocaleString())+' kW</strong></div><div class="sp-metric"><small>AC Output</small><strong>'+(pout===null?'—':pout.toLocaleString())+' kW</strong></div><div class="sp-metric"><small>Efficiency</small><strong>'+(eff===null?'—':eff.toFixed(1)+'%')+'</strong></div><div class="sp-metric"><small>Active Energy</small><strong>'+(energy===null?'—':energy.toLocaleString())+' kWh</strong></div><div class="sp-metric"><small>DC Inputs</small><strong>'+currents.length+'</strong></div><div class="sp-metric"><small>Median Current</small><strong>'+(median?median.toFixed(2):'—')+' A</strong></div></div><div class="sp-strings">'+currents.map(k=>{const v=Number(d[k]),ratio=median>0?v/median:1,cls=ratio<.6?'bad':ratio<.8?'low':'';return '<div class="sp-string '+cls+'"><small>'+esc(k.replace('in_dca_','String '))+'</small><b>'+v.toFixed(2)+' A</b></div>'}).join('')+'</div></article>')});grid.innerHTML=cards.join('');document.getElementById('spEmpty').hidden=cards.length>0;const efficiency=totalIn>1?totalOut/totalIn*100:null;document.getElementById('spSummary').innerHTML='<div class="sp-stat"><small>Inverter Online</small><strong>'+online+' / '+Object.keys(devices).length+'</strong></div><div class="sp-stat"><small>DC Input รวม</small><strong>'+totalIn.toLocaleString(undefined,{maximumFractionDigits:2})+' <span>kW</span></strong></div><div class="sp-stat"><small>AC Output รวม</small><strong>'+totalOut.toLocaleString(undefined,{maximumFractionDigits:2})+' <span>kW</span></strong></div><div class="sp-stat"><small>Conversion Efficiency</small><strong>'+(efficiency===null?'—':efficiency.toFixed(1))+' <span>% · แจ้งเตือน '+alerts+'</span></strong></div>'}
function load(){fetch('./api_mdbiotx.php',{cache:'no-store'}).then(r=>r.json()).then(p=>{latest=p.data||{};Object.values(latest).forEach(d=>{if(d&&['0','false','null','none',''].includes(String(d.error??'').trim().toLowerCase()))d.error=0;});document.getElementById('spUpdated').innerHTML='<i class="fa-solid fa-circle"></i> อัปเดต '+(p.dt||new Date().toLocaleTimeString('th-TH',{hour12:false}));draw()}).catch(()=>document.getElementById('spUpdated').textContent='โหลดข้อมูลไม่สำเร็จ')}search.addEventListener('input',draw);status.addEventListener('change',draw);load();setInterval(load,5000)})();
</script>
<script>
(()=>{const mapping=<?php echo json_encode($spChannelConfig,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>,grid=document.getElementById('spGrid');if(!grid)return;const apply=()=>{grid.querySelectorAll('.sp-card').forEach(card=>{const meta=card.querySelector('.sp-card-head small')?.textContent||'',id=meta.split('·')[0].trim(),rows=mapping[id],container=card.querySelector('.sp-strings');if(!container||!Array.isArray(rows)||!rows.length)return;const items=new Map([...container.querySelectorAll('.sp-string')].map(item=>{const number=(item.querySelector('small')?.textContent||'').match(/\d+$/)?.[0];return [number,item]}));container.className='sp-strings sp-channel-diagram';container.innerHTML='';rows.forEach((row,index)=>{const parameters=(Array.isArray(row.parameters)?row.parameters:[row.parameter]).filter(Boolean).sort((a,b)=>Number(String(a).match(/\d+/))-Number(String(b).match(/\d+/))),strings=parameters.map(parameter=>{const number=String(parameter).match(/\d+$/)?.[0],item=items.get(number);if(!item)return null;const label=item.querySelector('small');if(label)label.textContent='String '+number;return item}).filter(Boolean);if(!strings.length)return;const values=strings.map(item=>Number.parseFloat(item.querySelector('b')?.textContent)||0),max=Math.max(...values,1),group=document.createElement('section'),name=document.createElement('b');group.className='sp-channel-group';group.innerHTML='<div class="sp-channel-node"><span><i class="fa-solid fa-chart-simple"></i></span><div class="sp-channel-title"></div><small>'+strings.length+' Strings</small></div><div class="sp-channel-strings"></div>';name.textContent=row.channel||'Channel '+(index+1);group.querySelector('.sp-channel-title').appendChild(name);strings.forEach((item,i)=>{item.style.setProperty('--level',Math.max(2,values[i]/max*100)+'%');group.querySelector('.sp-channel-strings').appendChild(item)});container.appendChild(group)});if(!container.children.length)container.innerHTML='<div class="sp-channel-empty">ยังไม่มี String ที่มีข้อมูลใน Channel ที่ตั้งค่าไว้</div>'});};new MutationObserver(apply).observe(grid,{childList:true});apply();})();
</script>
</template>
